<?php
require_once __DIR__.'/RecipeInventory.php';
require_once __DIR__.'/CheckoutPolicy.php';
require_once __DIR__.'/User.php';
require_once __DIR__.'/ActivityLog.php';
class Promotion {
 public static function migrate($db){
  $db->query("CREATE TABLE IF NOT EXISTS promotions(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,description VARCHAR(500) NOT NULL,code VARCHAR(40) NULL UNIQUE,discount_type VARCHAR(12) NOT NULL,value_cents BIGINT NOT NULL,min_cents BIGINT NOT NULL DEFAULT 0,max_cents BIGINT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,channel VARCHAR(10) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'draft',usage_limit INT NULL,customer_limit INT NULL,created_by INT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(status,starts_at,ends_at)) ENGINE=InnoDB");
  $db->query("CREATE TABLE IF NOT EXISTS promotion_targets(promotion_id INT NOT NULL,target_type VARCHAR(12) NOT NULL,target_id INT NOT NULL,PRIMARY KEY(promotion_id,target_type,target_id)) ENGINE=InnoDB");
  $db->query("CREATE TABLE IF NOT EXISTS promotion_redemptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,promotion_id INT NOT NULL,branch_id INT NOT NULL,customer_id INT NULL,sale_id INT NULL UNIQUE,order_id INT NULL UNIQUE,status VARCHAR(12) NOT NULL,discount_cents BIGINT NOT NULL,subtotal_cents BIGINT NOT NULL,net_cents BIGINT NOT NULL,snapshot LONGTEXT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(promotion_id,status,customer_id),INDEX(branch_id,created_at)) ENGINE=InnoDB");
  $db->query("CREATE TABLE IF NOT EXISTS discount_approvals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cashier_id INT NOT NULL,branch_id INT NOT NULL,request_hash CHAR(64) NOT NULL,amount_cents BIGINT NOT NULL,reason VARCHAR(255) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'pending',approved_by INT NULL,sale_id INT NULL UNIQUE,created_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,INDEX(cashier_id,status)) ENGINE=InnoDB");
  $catalog=require __DIR__.'/../config/permissions.php';
  foreach($catalog as $name=>$info){if($info[1]!=='Promotions')continue;$s=$db->prepare('SELECT id FROM permissions WHERE name=?');$s->bind_param('s',$name);$s->execute();if($s->get_result()->num_rows)continue;$s=$db->prepare('INSERT INTO permissions(name,description,module) VALUES(?,?,?)');$s->bind_param('sss',$name,$info[0],$info[1]);$s->execute();$pid=(int)$db->insert_id;
   $db->query("INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT id,$pid FROM roles WHERE LOWER(REPLACE(REPLACE(REPLACE(name,' ',''),'_',''),'-','')) IN ('admin','superadmin')");
   if($name==='apply_manual_discounts')$db->query("INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT rp.role_id,$pid FROM role_permissions rp JOIN permissions p ON p.id=rp.permission_id WHERE p.name='access_pos'");
  }
  $db->query("INSERT IGNORE INTO settings(setting_key,setting_value,category) VALUES('cashier_discount_max_percent','10','financial')");
 }
 public static function ready(){return (bool)RecipeInventory::rows("SHOW TABLES LIKE 'promotions'");}
 public static function can($permission,$actor=null){return User::has_permission($actor??($_SESSION['user']['id']??0),$permission);}
 private static function now(){return (new DateTimeImmutable('now',new DateTimeZone('Asia/Manila')))->format('Y-m-d H:i:s');}
 private static function ids($v){if(!is_array($v)||count($v)>1000)throw new DomainException('Invalid promotion targets.');$out=[];foreach($v as $id){if(!ctype_digit((string)$id)||(int)$id<1)throw new DomainException('Invalid target ID.');$out[]=(int)$id;}return array_values(array_unique($out));}
 public static function save($input,$actor){
  $id=(int)($input['id']??0);if(!self::can($id?'edit_promotions':'create_promotions',$actor)||!User::has_all_branch_access($actor))throw new DomainException('Global promotion management permission is required.');
  $name=trim($input['name']??'');$description=trim($input['description']??'');$code=strtoupper(trim($input['code']??''));
  if(!$name||mb_strlen($name)>120||mb_strlen($description)>500||($code!==''&&!preg_match('/^[A-Z0-9_-]{3,40}$/D',$code)))throw new DomainException('Enter a name up to 120 characters and an optional code with 3–40 letters, digits, dashes or underscores.');
  $type=$input['discount_type']??'';$channel=$input['channel']??'';if(!in_array($type,['percent','fixed'],true)||!in_array($channel,['pos','online','both'],true))throw new DomainException('Choose a valid discount type and channel.');
  $value=CheckoutPolicy::cents($input['value']??'');$min=CheckoutPolicy::cents($input['minimum']??'0');$max=($input['maximum']??'')===''?null:CheckoutPolicy::cents($input['maximum']);
  if($value<=0||($type==='percent'&&$value>10000)||($max!==null&&$max<=0))throw new DomainException('Choose a positive discount; percentages cannot exceed 100.');
  $dates=[];foreach(['starts_at','ends_at'] as $field){$raw=str_replace('T',' ',$input[$field]??'');$d=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$raw,new DateTimeZone('Asia/Manila'));if(!$d||$d->format('Y-m-d H:i')!==$raw)throw new DomainException('Enter valid start and end dates.');$dates[]=$d->format('Y-m-d H:i:s');}if($dates[1]<=$dates[0])throw new DomainException('The end must be after the start.');
  $limits=[];foreach(['usage_limit','customer_limit'] as $k){$v=$input[$k]??'';if($v!==''&&(!ctype_digit((string)$v)||(int)$v<1||(int)$v>100000000))throw new DomainException('Usage limits must be positive whole numbers.');$limits[]=$v===''?null:(int)$v;}
  $targets=[];foreach(['branch'=>'branches','product'=>'products','category'=>'categories'] as $kind=>$table){$targets[$kind]=self::ids($input[$table]??[]);foreach($targets[$kind] as $target)if(!RecipeInventory::rows("SELECT id FROM $table WHERE id=?",'i',[$target]))throw new DomainException('A selected target no longer exists.');}
  return RecipeInventory::atomic(function()use($id,$name,$description,$code,$type,$value,$min,$max,$dates,$channel,$limits,$targets,$actor){
   $now=self::now();$code=$code===''?null:$code;
   if($id){$old=RecipeInventory::rows('SELECT * FROM promotions WHERE id=? FOR UPDATE','i',[$id]);if(!$old||$old[0]['status']==='archived')throw new DomainException('Promotion is unavailable.');if($old[0]['status']==='active')throw new DomainException('Pause the promotion before editing its rules.');
    RecipeInventory::query('UPDATE promotions SET name=?,description=?,code=?,discount_type=?,value_cents=?,min_cents=?,max_cents=?,starts_at=?,ends_at=?,channel=?,usage_limit=?,customer_limit=?,updated_at=? WHERE id=?','ssssiiisssiisi',[$name,$description,$code,$type,$value,$min,$max,$dates[0],$dates[1],$channel,$limits[0],$limits[1],$now,$id]);
   }else{RecipeInventory::query("INSERT INTO promotions(name,description,code,discount_type,value_cents,min_cents,max_cents,starts_at,ends_at,channel,usage_limit,customer_limit,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",'ssssiiisssiiiss',[$name,$description,$code,$type,$value,$min,$max,$dates[0],$dates[1],$channel,$limits[0],$limits[1],$actor,$now,$now]);$id=$GLOBALS['conn']->insert_id;}
   RecipeInventory::query('DELETE FROM promotion_targets WHERE promotion_id=?','i',[$id]);foreach($targets as $kind=>$ids)foreach($ids as $target)RecipeInventory::query('INSERT INTO promotion_targets VALUES(?,?,?)','isi',[$id,$kind,$target]);
   ActivityLog::log('Promotion saved','Promotion #'.$id.' saved.');return $id;
  });
 }
 public static function status($id,$status,$actor){if(!self::can('activate_promotions',$actor)||!User::has_all_branch_access($actor)||!in_array($status,['active','paused','archived'],true))throw new DomainException('You cannot change promotion status.');return RecipeInventory::atomic(function()use($id,$status){$r=RecipeInventory::rows('SELECT * FROM promotions WHERE id=? FOR UPDATE','i',[$id]);if(!$r||$r[0]['status']==='archived')throw new DomainException('Promotion is unavailable.');RecipeInventory::query('UPDATE promotions SET status=?,updated_at=? WHERE id=?','ssi',[$status,self::now(),$id]);ActivityLog::log('Promotion status','Promotion #'.$id.' changed to '.$status);});}
 public static function targets($id){return RecipeInventory::rows('SELECT target_type,target_id FROM promotion_targets WHERE promotion_id=?','i',[$id]);}
 public static function quote(array $quotes,$branch,$channel,$customer=null,$code='',$lock=false){
  $subtotal=0;$eligible=0;foreach($quotes as $q){$line=$q['price_cents']*$q['quantity'];$subtotal+=$line;if(!empty($q['product']['is_discountable']))$eligible+=$line;}
  $none=['promotion'=>null,'discount_cents'=>0,'eligible_cents'=>$eligible,'subtotal_cents'=>$subtotal];
  if(!self::ready())return $none;
  if(!is_string($code)||strlen($code)>40)throw new DomainException('Invalid promo code.');$code=strtoupper(trim($code));if($code==='')return $none;
  if(Setting::get('discount_enabled','1')!=='1'){if($code!=='')throw new DomainException('Discounts are disabled.');return $none;}
  $sql="SELECT * FROM promotions WHERE status='active' AND channel IN (?, 'both') AND starts_at<=? AND ends_at>? AND ".(preg_match('/^@OFFER:[1-9][0-9]*$/D',$code)?'id=?':'code=?').' ORDER BY id'.($lock?' FOR UPDATE':'');$now=self::now();$params=[$channel,$now,$now];$types='sss';if($code!==''){$selected=preg_match('/^@OFFER:([1-9][0-9]*)$/D',$code,$match);$params[]=$selected?(int)$match[1]:$code;$types.=$selected?'i':'s';}
  $best=$none;
  foreach(RecipeInventory::rows($sql,$types,$params) as $p){
   $targets=RecipeInventory::rows('SELECT target_type,target_id FROM promotion_targets WHERE promotion_id=?'.($lock?' FOR UPDATE':''),'i',[$p['id']]);$groups=['branch'=>[],'product'=>[],'category'=>[]];foreach($targets as $t)$groups[$t['target_type']][]=(int)$t['target_id'];
   if($groups['branch']&&!in_array((int)$branch,$groups['branch'],true))continue;
   if($subtotal<(int)$p['min_cents'])continue;
   $base=0;foreach($quotes as $q){$product=$q['product'];if(empty($product['is_discountable']))continue;if(($groups['product']||$groups['category'])&&!in_array((int)$product['id'],$groups['product'],true)&&!in_array((int)$product['category_id'],$groups['category'],true))continue;$base+=$q['price_cents']*$q['quantity'];}
   if(!$base)continue;
   $used=RecipeInventory::rows("SELECT customer_id FROM promotion_redemptions WHERE promotion_id=? AND status IN ('reserved','completed','refunded')".($lock?' FOR UPDATE':''),'i',[$p['id']]);$count=['n'=>count($used),'customer_n'=>count(array_filter($used,function($r)use($customer){return $customer&&(int)$r['customer_id']===(int)$customer;}))];
   if($p['usage_limit']!==null&&(int)$count['n']>=(int)$p['usage_limit'])continue;
   if($p['customer_limit']!==null&&(!$customer||(int)$count['customer_n']>=(int)$p['customer_limit']))continue;
   $amount=$p['discount_type']==='percent'?(int)round($base*$p['value_cents']/10000):min($base,(int)$p['value_cents']);
   if($p['max_cents']!==null)$amount=min($amount,(int)$p['max_cents']);$cap=CheckoutPolicy::cents(Setting::get('discount_max_percent','100'));$amount=min($amount,intdiv($eligible*$cap,10000),$base);
   if($amount>$best['discount_cents'])$best=['promotion'=>['id'=>(int)$p['id'],'name'=>$p['name'],'code'=>$p['code'],'type'=>$p['discount_type'],'value_cents'=>(int)$p['value_cents'],'eligible_cents'=>$base],'discount_cents'=>$amount,'eligible_cents'=>$eligible,'subtotal_cents'=>$subtotal];
  }
  if($code!==''&&!$best['promotion'])throw new DomainException('Promo code is invalid, expired, exhausted, or not eligible for this cart and branch.');return $best;
 }
 public static function available($quotes,$branch,$channel,$customer=null){
  if(!self::ready())return [];$now=self::now();$out=[];
  foreach(RecipeInventory::rows("SELECT * FROM promotions WHERE status='active' AND channel IN (?, 'both') AND starts_at<=? AND ends_at>? ORDER BY name,id",'sss',[$channel,$now,$now]) as $p){
   $targets=self::targets($p['id']);$branches=[];foreach($targets as $t)if($t['target_type']==='branch')$branches[]=(int)$t['target_id'];if($branches&&!in_array((int)$branch,$branches,true))continue;
   $key=$p['code']?:'@OFFER:'.$p['id'];$eligible=true;$reason='';$discount=0;try{$q=self::quote($quotes,$branch,$channel,$customer,$key);$discount=$q['discount_cents'];}catch(DomainException $e){$eligible=false;$reason=$p['customer_limit']!==null&&!$customer?'Identify a customer to use this offer.':'Not eligible for this cart, or the usage limit has been reached.';}
   $out[]=['name'=>$p['name'],'description'=>$p['description'],'code'=>$p['code'],'selection'=>$key,'type'=>$p['discount_type'],'value'=>$p['value_cents']/100,'minimum'=>$p['min_cents']/100,'maximum'=>$p['max_cents']===null?null:$p['max_cents']/100,'ends_at'=>$p['ends_at'],'eligible'=>$eligible,'reason'=>$reason,'savings'=>$discount/100];
  }return $out;
 }
 public static function posQuotes($cart,$branch){$quotes=[];foreach($cart as $item)$quotes[]=RecipeInventory::quoteItem((int)($item['product_id']??$item['id']),$item['quantity'],$item['modifiers']??[],$branch);return $quotes;}
 public static function cartQuotes(array $cart){$quotes=[];foreach($cart as $item){$p=Product::find_by_id($item['product_id']??$item['id']);if(!$p)throw new DomainException('A cart product is unavailable.');$quantity=$item['quantity']??$item['qty'];$line=CheckoutPolicy::cents(number_format((float)($item['subtotal']??($item['price']*$quantity)),2,'.',''));$quotes[]=['product'=>$p,'quantity'=>1,'price_cents'=>$line];}return $quotes;}
 public static function financial($quotes,$branch,$channel,$customer,$code='',$manual='0',$lock=false,$actor=null,$approval=null){
  $q=self::quote($quotes,$branch,$channel,$customer,$code,$lock);$amount=CheckoutPolicy::cents((string)$manual);
  if($amount){if(trim($code)!=='')throw new DomainException('A manual discount cannot be combined with a promo code.');if($actor!==null)$approval=self::assertManual($actor,$branch,$quotes,$amount,$approval,$lock);$q['promotion']=null;$q['discount_cents']=$amount;}
  $f=CheckoutPolicy::calculate($q['subtotal_cents'],$q['eligible_cents'],number_format($q['discount_cents']/100,2,'.',''));$f['promotion']=$q['promotion'];if($amount)$f['manual_discount']=['actor'=>$actor,'approval_id'=>$approval];return $f;
 }
 public static function redeem($f,$branch,$customer,$sale=null,$order=null){if(empty($f['promotion']))return;$now=self::now();RecipeInventory::query('INSERT INTO promotion_redemptions(promotion_id,branch_id,customer_id,sale_id,order_id,status,discount_cents,subtotal_cents,net_cents,snapshot,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)','iiiiisiiisss',[$f['promotion']['id'],$branch,$customer,$sale,$order,$sale?'completed':'reserved',$f['discount_cents'],$f['subtotal_cents'],$f['total_cents'],json_encode($f,JSON_THROW_ON_ERROR),$now,$now]);}
 public static function settle($order,$sale){if(!self::ready())return;RecipeInventory::query("UPDATE promotion_redemptions SET sale_id=?,status='completed',updated_at=? WHERE order_id=? AND status='reserved'",'isi',[$sale,self::now(),$order]);}
 public static function cancel($order){if(self::ready())RecipeInventory::query("UPDATE promotion_redemptions SET status='released',updated_at=? WHERE order_id=? AND status='reserved'",'si',[self::now(),$order]);}
 public static function refund($sale){if(self::ready())RecipeInventory::query("UPDATE promotion_redemptions SET status='refunded',updated_at=? WHERE sale_id=? AND status='completed'",'si',[self::now(),$sale]);}
 public static function hash($branch,$quotes,$amount){return hash('sha256',json_encode([(int)$branch,array_map(function($q){return [(int)$q['product']['id'],$q['quantity'],$q['price_cents'],(bool)$q['product']['is_discountable'],$q['modifiers']??[]];},$quotes),$amount]));}
 public static function requestApproval($actor,$branch,$quotes,$amount,$reason){if(!self::can('apply_manual_discounts',$actor))throw new DomainException('Manual discount permission is required.');$reason=trim($reason);if(mb_strlen($reason)<5||mb_strlen($reason)>255)throw new DomainException('Enter an approval reason with 5–255 characters.');$cents=CheckoutPolicy::cents($amount);CheckoutPolicy::cart($_SESSION['pos_cart']??[],$amount);if(!$cents)throw new DomainException('Enter a positive manual discount.');$now=self::now();$hash=self::hash($branch,$quotes,$cents);RecipeInventory::query("INSERT INTO discount_approvals(cashier_id,branch_id,request_hash,amount_cents,reason,created_at,expires_at) VALUES(?,?,?,?,?,?,DATE_ADD(?,INTERVAL 30 MINUTE))",'iisisss',[$actor,$branch,$hash,$cents,$reason,$now,$now]);$id=$GLOBALS['conn']->insert_id;ActivityLog::log('Discount approval requested','Requested approval #'.$id);return $id;}
 public static function assertManual($actor,$branch,$quotes,$amount,$approval,$lock){if(!self::can('apply_manual_discounts',$actor))throw new DomainException('You cannot apply manual discounts.');$eligible=0;foreach($quotes as $q)if(!empty($q['product']['is_discountable']))$eligible+=$q['price_cents']*$q['quantity'];$cap=CheckoutPolicy::cents(Setting::get('cashier_discount_max_percent','10'));if(self::can('approve_discount_overrides',$actor)||$amount<=intdiv($eligible*$cap,10000))return null;
  $r=RecipeInventory::rows("SELECT * FROM discount_approvals WHERE id=? AND cashier_id=? AND branch_id=? AND status='approved' AND expires_at>?".($lock?' FOR UPDATE':''),'iiis',[(int)$approval,$actor,$branch,self::now()]);if(!$r||!hash_equals($r[0]['request_hash'],self::hash($branch,$quotes,$amount))||!self::can('approve_discount_overrides',$r[0]['approved_by']))throw new DomainException('This discount requires supervisor approval for the current cart. Request approval in the POS.');return (int)$r[0]['id'];
 }
 public static function approve($id,$actor,$decision){if(!self::can('approve_discount_overrides',$actor)||!in_array($decision,['approved','rejected'],true))throw new DomainException('Approval permission is required.');return RecipeInventory::atomic(function()use($id,$actor,$decision){$r=RecipeInventory::rows("SELECT * FROM discount_approvals WHERE id=? AND status='pending' AND expires_at>? FOR UPDATE",'is',[$id,self::now()]);if(!$r||$r[0]['cashier_id']==$actor)throw new DomainException('This request is unavailable or belongs to you.');$ctx=User::access_context($actor);if(!$ctx['global']&&(int)$ctx['branch_id']!==(int)$r[0]['branch_id'])throw new DomainException('This request belongs to another branch.');RecipeInventory::query('UPDATE discount_approvals SET status=?,approved_by=? WHERE id=?','sii',[$decision,$actor,$id]);ActivityLog::log('Discount '.$decision,'Request #'.$id);});}
}
